# Validate inputs
for arr, name in [(logp_with_result, 'logp_with_result'), (logp_call_only, 'logp_call_only'), (logp_no_call, 'logp_no_call')]:
    if not isinstance(arr, np.ndarray):
        raise ValueError(f"{name} must be a numpy array")
    if arr.ndim != 2:
        raise ValueError(f"{name} must be a 2D matrix")
    if arr.size == 0:
        raise ValueError(f"{name} must not be empty")
    if not np.all(np.isfinite(arr)):
        raise ValueError(f"{name} contains non-finite values")
    if np.any(arr > 0):
        raise ValueError(f"{name} has positive values")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All input matrices must have the same shape")
if isinstance(tau_filter, (bool, np.bool_)):
    raise ValueError("tau_filter cannot be boolean")
if not isinstance(tau_filter, (int, float, np.integer, np.floating)):
    raise ValueError("tau_filter must be a numeric value")
if tau_filter < 0 or not np.isfinite(tau_filter):
    raise ValueError("tau_filter must be a nonnegative finite number")
future_horizon = logp_with_result.shape[1]
if future_horizon == 0:
    raise ValueError("future horizon must be positive")
t = np.arange(future_horizon, dtype=float)
raw = np.maximum(0.0, 1.0 - 0.2 * t)
norm_weights = raw / raw.sum()
L_plus = -np.sum(logp_with_result * norm_weights, axis=1)
L_call_only = -np.sum(logp_call_only * norm_weights, axis=1)
L_no_call = -np.sum(logp_no_call * norm_weights, axis=1)
L_minus = np.minimum(L_no_call, L_call_only)
margin = L_minus - L_plus
keep_mask = margin >= tau_filter
return keep_mask, margin
